<?php
 namespace QQWorld\Setup\Test\Unit\Model; use QQWorld\Setup\Model\ModuleUninstaller; class ModuleUninstallerTest extends \PHPUnit\Framework\TestCase { private $objectManager; private $remove; private $collector; private $setup; private $uninstaller; private $output; private $moduleRegistryUninstaller; public function setUp() { $this->moduleRegistryUninstaller = $this->createMock(\QQWorld\Setup\Model\ModuleRegistryUninstaller::class); $this->objectManager = $this->getMockForAbstractClass( \QQWorld\Framework\ObjectManagerInterface::class, [], '', false ); $objectManagerProvider = $this->createMock(\QQWorld\Setup\Model\ObjectManagerProvider::class); $objectManagerProvider->expects($this->once())->method('get')->willReturn($this->objectManager); $this->remove = $this->createMock(\QQWorld\Framework\Composer\Remove::class); $this->collector = $this->createMock(\QQWorld\Setup\Model\UninstallCollector::class); $this->setup = $this->createMock(\QQWorld\Setup\Module\Setup::class); $setupFactory = $this->createMock(\QQWorld\Setup\Module\SetupFactory::class); $setupFactory->expects($this->any())->method('create')->willReturn($this->setup); $this->uninstaller = new ModuleUninstaller( $objectManagerProvider, $this->remove, $this->collector, $setupFactory, $this->moduleRegistryUninstaller ); $this->output = $this->createMock(\Symfony\Component\Console\Output\OutputInterface::class); } public function testUninstallRemoveData() { $this->moduleRegistryUninstaller->expects($this->never())->method($this->anything()); $uninstall = $this->getMockForAbstractClass(\QQWorld\Framework\Setup\UninstallInterface::class, [], '', false); $uninstall->expects($this->atLeastOnce()) ->method('uninstall') ->with($this->setup, $this->isInstanceOf(\QQWorld\Setup\Model\ModuleContext::class)); $this->collector->expects($this->once()) ->method('collectUninstall') ->willReturn(['moduleA' => $uninstall, 'moduleB' => $uninstall]); $resource = $this->createMock(\QQWorld\Framework\Module\ModuleResource::class); $resource->expects($this->atLeastOnce())->method('getDbVersion')->willReturn('1.0'); $this->output->expects($this->atLeastOnce())->method('writeln'); $this->objectManager->expects($this->once()) ->method('get') ->with(\QQWorld\Framework\Module\ModuleResource::class) ->willReturn($resource); $this->uninstaller->uninstallData($this->output, ['moduleA', 'moduleB']); } public function testUninstallRemoveCode() { $this->moduleRegistryUninstaller->expects($this->never())->method($this->anything()); $this->output->expects($this->once())->method('writeln'); $packageInfoFactory = $this->createMock(\QQWorld\Framework\Module\PackageInfoFactory::class); $packageInfo = $this->createMock(\QQWorld\Framework\Module\PackageInfo::class); $packageInfo->expects($this->atLeastOnce())->method('getPackageName'); $packageInfoFactory->expects($this->once())->method('create')->willReturn($packageInfo); $this->objectManager->expects($this->once()) ->method('get') ->with(\QQWorld\Framework\Module\PackageInfoFactory::class) ->willReturn($packageInfoFactory); $this->remove->expects($this->once())->method('remove'); $this->uninstaller->uninstallCode($this->output, ['moduleA', 'moduleB']); } } 